// wasm-loader.js
//
// Loads the Leptos web component.
//
// Preferred path: the wasm-bindgen glue (`lx_counter.js` + its `.wasm`),
// generated by `cargo build --release --target wasm32-unknown-unknown`
// followed by `wasm-bindgen --target web`. The glue does its own
// WebAssembly instantiation and exports `__meta_Card`/`__mount_Card`/
// `__update_Card`/`__unmount_Card` plus `init`.
//
// Fallback path: if the glue or .wasm is missing (e.g. fresh checkout
// before a Rust build), a JS polyfill implements the same contract so
// the demo still renders.

export async function loadLeptosWASM() {
  try {
    const glue = await import("./lx_counter.js");
    // wasm-bindgen's standard entry: default export is the async init
    // that instantiates the .wasm; named exports are the component fns.
    if (typeof glue.default === "function") {
      await glue.default();
    } else if (typeof glue.init === "function") {
      await glue.init();
    }
    const exports = {
      __meta_Card: () => {
        return JSON.stringify({
          tag: "lx-card",
          mount: "__mount_Card",
          update: "__update_Card",
          unmount: "__unmount_Card",
          attrs: ["label", "description"],
        });
      },
      __mount_Card: glue.__mount_Card,
      __update_Card: glue.__update_Card,
      __unmount_Card: glue.__unmount_Card,
      _isWASM: true,
    };
    return exports;
  } catch (e) {
    // Glue missing or failed to init — use the JS polyfill.
    return loadFallbackImplementation();
  }
}

function loadFallbackImplementation() {
  // A working JS implementation that mimics the WASM component. Used
  // only when the real WASM build isn't present.
  return {
    __meta_Card: () => {
      return JSON.stringify({
        tag: "lx-card",
        mount: "__mount_Card",
        update: "__update_Card",
        unmount: "__unmount_Card",
        attrs: ["label", "description"],
      });
    },

    __mount_Card: (host, propsJson) => {
      try {
        const props = JSON.parse(propsJson);
        const shadow = host.attachShadow({ mode: "open" });
        renderCard(shadow, props, host);
      } catch (e) {
        host.innerHTML = `<div style="border: 1px solid #fff; padding: 1.5rem; color: #fff">Leptos card</div>`;
      }
    },

    __update_Card: (host, propsJson) => {
      try {
        const props = JSON.parse(propsJson);
        const shadow = host.shadowRoot;
        if (shadow) renderCard(shadow, props, host);
      } catch (e) {
        // ignore
      }
    },

    __unmount_Card: (host) => {
      host.shadowRoot?.remove?.();
    },
  };
}

function renderCard(shadow, props, host) {
  const label = props.label || "Leptos";
  const description = props.description || "";
  shadow.innerHTML = `
    <style>
      :host { display: block; }
      .card {
        background: var(--wc-color-primary, #000);
        color: var(--wc-color-text, #fff);
        border: 1px solid var(--wc-color-text, #fff);
        padding: 1.5rem; min-height: 200px; display: flex;
        flex-direction: column; cursor: pointer;
        font-family: var(--wc-font, system-ui, sans-serif);
      }
      h3 { margin: 0 0 0.6rem; text-transform: uppercase; font-size: 1.4rem; }
      p { flex: 1; margin: 0; font-size: 0.95rem; color: #ddd; }
      .tag {
        align-self: flex-start; margin-top: 1rem; font-size: 0.7rem;
        text-transform: uppercase; letter-spacing: 0.12em;
        border: 1px solid var(--wc-color-text, #fff);
        padding: 0.25rem 0.6rem; color: var(--wc-color-text, #fff);
      }
    </style>
    <article class="card">
      <h3>${label}</h3>
      <p>${description}</p>
      <span class="tag">Leptos</span>
    </article>`;

  shadow.querySelector(".card")?.addEventListener("click", () => {
    host.dispatchEvent(new CustomEvent("card-clicked", { detail: { label } }));
  });
}